import { useId } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Label } from "@/registry/default/ui/label";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/registry/default/ui/select";

const Square = ({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) => (
  <span
    aria-hidden="true"
    className={cn(
      "flex size-5 items-center justify-center rounded bg-muted font-medium text-muted-foreground text-xs",
      className,
    )}
    data-square
  >
    {children}
  </span>
);

export default function Component() {
  const id = useId();
  return (
    <div className="*:not-first:mt-2">
      <Label htmlFor={id}>خيارات مع الصورة الرمزية النائب</Label>
      <Select defaultValue="1">
        <SelectTrigger
          className="ps-2 [&>span]:flex [&>span]:items-center [&>span]:gap-2 [&>span_[data-square]]:shrink-0"
          id={id}
        >
          <SelectValue placeholder="اختر إطار العمل" />
        </SelectTrigger>
        <SelectContent className="[&_*[role=option]>span]:start-auto [&_*[role=option]>span]:end-2 [&_*[role=option]>span]:flex [&_*[role=option]>span]:items-center [&_*[role=option]>span]:gap-2 [&_*[role=option]]:ps-2 [&_*[role=option]]:pe-8">
          <SelectGroup>
            <SelectLabel className="ps-2">انتحال شخصية المستخدم</SelectLabel>
            <SelectItem value="1">
              <Square className="bg-indigo-400/20 text-indigo-500">و</Square>
              <span className="truncate">فرانك موريس</span>
            </SelectItem>
            <SelectItem value="2">
              <Square className="bg-purple-400/20 text-purple-500">X</Square>
              <span className="truncate">كزافيير غيرا</span>
            </SelectItem>
            <SelectItem value="3">
              <Square className="bg-rose-400/20 text-rose-500">أ</Square>
              <span className="truncate">آن كيلي</span>
            </SelectItem>
          </SelectGroup>
        </SelectContent>
      </Select>
    </div>
  );
}
